/** The host binds its commonDictionary and product names once; `t` falls back to the common copy on a miss. */
export function createSettingsCapabilitiesDictionary(
  { commonDictionary, productName, referenceProductName }: { commonDictionary: Readonly<Record<string, Readonly<Record<string, string>>>>; productName: string; referenceProductName: string },
  _optional = {},
): { t: DictionaryTranslator } {
  const featureDictionary = bindDictionaryNames({ dictionary: SETTINGS_CAPABILITIES_DICT, names: { productName, referenceProductName } });
  return { t: createDictionaryTranslator({ featureDictionary }, { commonDictionary }) };
}
